(()=>{
const projects={adda:['عضّة','ADDA','مطاعم وتجربة طلب تفاعلية','Restaurant & interactive ordering'],skyward:['سكاي وارد','Skyward Travel','سياحة واستكشاف الوجهات','Travel & destination discovery'],caffaino:['كافاينو','CAFFAINO','قهوة وتجربة بصرية','Coffee & visual storytelling']};
const dialog=document.querySelector('.project-dialog'),frame=dialog.querySelector('iframe'),full=dialog.querySelector('.project-full'),close=dialog.querySelector('button');let active=null,opener;
const en=()=>document.documentElement.lang==='en';
function localize(){Object.entries(projects).forEach(([id,p])=>{document.querySelector('[data-project-name="'+id+'"]').textContent=p[en()?1:0];document.querySelector('[data-project-category="'+id+'"]').textContent=p[en()?3:2];const a=document.querySelector('[data-preview="'+id+'"]');a.setAttribute('aria-label',(en()?'Preview ':'معاينة ')+p[en()?1:0]);a.querySelector('img').alt=p[en()?1:0];a.querySelector('span').textContent=en()?'Try the website ↗':'جرّب الموقع ↗';a.closest('article').querySelector('.project-external').setAttribute('aria-label',(en()?'Open website: ':'فتح الموقع: ')+p[en()?1:0]);});full.textContent=en()?'Open full website ↗':'فتح الموقع كاملًا ↗';close.setAttribute('aria-label',en()?'Close preview':'إغلاق المعاينة');if(active){document.querySelector('#project-dialog-title').textContent=projects[active][en()?1:0];frame.title=(en()?'Preview: ':'معاينة: ')+projects[active][en()?1:0];}}
document.querySelectorAll('[data-preview]').forEach(a=>a.addEventListener('click',e=>{if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();opener=a;active=a.dataset.preview;frame.src=a.href;full.href=a.href;localize();dialog.showModal();document.body.style.overflow='hidden';}));
close.onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>{frame.removeAttribute('src');document.body.style.overflow='';opener?.focus();});new MutationObserver(localize).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});localize();
})();